// Android origin-scoped, main-frame-only messaging. No Java object is exposed to web frames.
(()=>{if(window.dawnCloud||window.top!==window)return;const pending=new Map();if(!window.DawnCloudPort)throw Error('Origin-scoped messaging is unavailable');const send=(command,options)=>new Promise((resolve,reject)=>{const id=crypto.randomUUID();pending.set(id,{resolve,reject});DawnCloudPort.postMessage(JSON.stringify({id,command,options}));});DawnCloudPort.onmessage=event=>{const reply=JSON.parse(event.data),item=pending.get(reply.id);if(!item)return;pending.delete(reply.id);reply.error?item.reject(Error(reply.error)):item.resolve(reply.value);};window.dawnCloud=Object.freeze({request:options=>send('request',options),clipboard:text=>send('clipboard',{text}),open:url=>send('open',{url}),download:options=>send('download',options)});})();
